<?php
declare(strict_types=1);
/* PRELAUNCH_20261103_V1 */
function renderAdmin():void{
 requireAdmin();$tab=(string)($_GET['tab']??'queue');if(!in_array($tab,['queue','users','reports','appeals','settings','audit','admins'],true))$tab='queue';echo '<a href="'.e(url()).'">← Ver site</a><div class="inline-actions"><a class="button outline" href="'.e(url('visual-editor')).'">Editor por clique</a><a class="button outline" href="/pre-lancamento/admin.php">Interessados no lançamento</a>';beginForm('logout','inline-form');submit('Sair do admin');echo '</div>';echo '<section class="page-heading"><p class="eyebrow">ADMINISTRAÇÃO</p><h1>Uma comunidade de boas trocas.</h1></section><nav class="account-nav">';foreach(['queue'=>'Moderação','users'=>'Usuários','reports'=>'Denúncias','appeals'=>'Contestações','settings'=>'Configurações','audit'=>'Registro de ações','admins'=>'Administradores'] as $key=>$name)echo '<a '.($tab===$key?'aria-current="page"':'').' href="'.e(url('admin',['tab'=>$key])).'">'.e($name).'</a>';echo '</nav>';
 if($tab==='queue'){
  $pending=(int)sql("SELECT COUNT(*) FROM listings WHERE status='PENDING'")->fetchColumn();$messages=(int)sql("SELECT COUNT(*) FROM messages WHERE status='PENDING'")->fetchColumn();$jobs=(int)sql("SELECT COUNT(*) FROM jobs WHERE status IN ('QUEUED','FAILED')")->fetchColumn();echo '<div class="stats"><article class="panel"><strong>'.$pending.'</strong><span>Anúncios em revisão</span></article><article class="panel"><strong>'.$messages.'</strong><span>Mensagens em revisão</span></article><article class="panel"><strong>'.$jobs.'</strong><span>Análises na fila</span></article></div><div class="notice">IA: '.(cfg()['ai']['enabled']&&cfg()['ai']['key']!==''?'configurada':'não ativada — revisão humana').'. Publicação automática: '.(cfg()['ai']['auto_publish']?'ativada após análise favorável':'desativada').'.';beginForm('process_jobs');submit('Processar próxima análise');echo '</div>';
  $filter=(string)($_GET['status']??'PENDING');if(!in_array($filter,['PENDING','ACTIVE','REJECTED','PAUSED'],true))$filter='PENDING';echo '<div class="inline-actions">';foreach(['PENDING','ACTIVE','REJECTED','PAUSED'] as $s)echo '<a href="'.e(url('admin',['status'=>$s])).'">'.pill($s).'</a>';echo '</div>';
  $items=sql('SELECT l.*,u.name,u.email FROM listings l JOIN users u ON u.id=l.user_id WHERE l.status=? ORDER BY l.id DESC LIMIT 100',[$filter])->fetchAll();echo '<h2>Anúncios</h2>';if(!$items)echo '<p>Nenhum anúncio nesta fila.</p>';foreach($items as $l){echo '<article class="panel admin-review"><div><h3>'.e($l['title']).'</h3><p>'.e($l['name']).' · '.e($l['city']).'/'.e($l['state']).'</p><p>'.e($l['moderation_reason']).' · '.e($l['moderation_source']).'</p>';$job=sql('SELECT last_error FROM jobs WHERE listing_id=? AND revision=? ORDER BY id DESC LIMIT 1',[$l['id'],$l['revision']])->fetch();if(!empty($job['last_error']))echo '<div class="notice error"><strong>Diagnóstico da IA:</strong> '.e($job['last_error']).'</div>';echo '<p>Interesses: '.e($l['wanted']).'</p><a class="button outline" href="'.e(url('listing',['id'=>$l['id']])).'" target="_blank">Conferir anúncio e fotos</a></div><div>';beginForm('admin_listing');hidden('id',$l['id']);selectField('status','Decisão',['ACTIVE'=>'Publicar','REJECTED'=>'Recusar','PAUSED'=>'Pausar'],$l['status']);area('reason','Motivo para o anunciante',$l['moderation_reason']??'',1000);submit('Registrar decisão');beginForm('retry_job','inline-form');hidden('id',$l['id']);submit('Enviar novamente à IA');echo '</div></article>';}
  echo '<h2>Mensagens sinalizadas</h2>';foreach(sql("SELECT m.*,u.name,l.title,p.offer_title FROM messages m JOIN users u ON u.id=m.sender_id JOIN proposals p ON p.id=m.proposal_id JOIN listings l ON l.id=p.listing_id WHERE m.status='PENDING' ORDER BY m.id LIMIT 100")->fetchAll() as $m){echo '<article class="panel"><h3>'.e($m['name']).' · '.e($m['title']).'</h3><p>Item oferecido: '.e($m['offer_title']).'</p><p class="preserve-text">'.e($m['body']).'</p><p>'.e($m['moderation_reason']).'</p>';beginForm('admin_message');hidden('id',$m['id']);selectField('status','Decisão',['ACTIVE'=>'Liberar mensagem','REJECTED'=>'Recusar mensagem']);field('reason','Motivo','Conteúdo revisado pela equipe.',max:1000);submit('Registrar revisão');echo '</article>';}
 }
 elseif($tab==='users'){
  if(isset($_SESSION['admin_recovery'])){echo '<div class="notice">Link de recuperação, válido por 30 minutos. Compartilhe apenas com o titular após confirmar sua identidade.<input class="copy-link" readonly value="'.e($_SESSION['admin_recovery']).'"></div>';unset($_SESSION['admin_recovery']);}
  $query=mb_substr(trim((string)($_GET['q']??'')),0,100);echo '<form class="admin-search" method="get"><input type="hidden" name="r" value="admin"><input type="hidden" name="tab" value="users"><label>Buscar por nome ou e-mail<input name="q" value="'.e($query).'"></label><button class="button outline">Buscar</button></form>';$like='%'.str_replace(['!','%','_'],['!!','!%','!_'],$query).'%';$users=sql("SELECT id,name,email,city,state,status,role,email_verified FROM users WHERE name LIKE ? ESCAPE '!' OR email LIKE ? ESCAPE '!' ORDER BY id DESC LIMIT 100",[$like,$like])->fetchAll();foreach($users as $u){echo '<article class="panel user-row"><div><h3>'.e($u['name']).'</h3><p>'.e($u['email']).' · '.e($u['city']).'/'.e($u['state']).'</p>'.pill($u['status']).'<p>'.((int)$u['email_verified']?'E-mail confirmado':'E-mail não confirmado').'</p></div><div class="inline-actions">';if($u['role']!=='ADMIN'&&$u['status']!=='CLOSED')foreach(['verify'=>'Confirmar e-mail após suporte','reset'=>'Gerar recuperação de senha',($u['status']==='ACTIVE'?'BANNED':'ACTIVE')=>($u['status']==='ACTIVE'?'Suspender usuário':'Reativar usuário')] as $do=>$label){beginForm('admin_user','inline-form');hidden('id',$u['id']);hidden('do',$do);submit($label);}else echo '<p>'.($u['role']==='ADMIN'?'Administrador':'Conta encerrada').'</p>';echo '</div>';if($u['role']!=='ADMIN'&&$u['status']!=='CLOSED'){echo '<details class="edit-user"><summary>Editar informações</summary>';beginForm('admin_profile');hidden('id',$u['id']);field('name','Nome',$u['name'],max:100);field('email','E-mail',$u['email'],type:'email',max:190);field('city','Cidade',$u['city'],max:120);stateSelect($u['state']);submit('Salvar dados');echo '</details>';}echo '</article>';}
 }
 elseif($tab==='reports'||$tab==='appeals'){
  $rows=sql("SELECT t.*,u.name FROM $tab t JOIN users u ON u.id=t.user_id ORDER BY (t.status='OPEN') DESC,t.id DESC LIMIT 100")->fetchAll();if(!$rows)echo '<div class="empty-state"><h2>Nenhuma revisão recebida.</h2></div>';foreach($rows as $row){echo '<article class="panel"><h3>#'.(int)$row['id'].' · '.e($row['name']).'</h3>'.pill($row['status']).'<p class="preserve-text">'.e($row['reason']).'</p>';if($row['listing_id']){echo '<p>Anúncio #'.(int)$row['listing_id'].' · <a target="_blank" href="'.e(url('listing',['id'=>$row['listing_id']])).'">Abrir conteúdo</a></p>';}$pid=(int)($row['proposal_id']??0);if($pid){$messages=sql('SELECT m.*,u.name FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.proposal_id=? ORDER BY m.id DESC LIMIT 20',[$pid])->fetchAll();echo '<details><summary>Mensagens da conversa denunciada #'.$pid.'</summary>';foreach($messages as $m)echo '<p><strong>'.e($m['name']).':</strong> '.e($m['body']).' '.pill($m['status']).'</p>';echo '</details>';}if($row['status']==='OPEN'){beginForm('admin_resolution');hidden('table',$tab);hidden('id',$row['id']);area('resolution','Resultado da análise (registrado para o solicitante)','',1500);submit('Concluir revisão');}else echo '<p>'.e($row['resolution']).'</p>';echo '</article>';}
 }
 elseif($tab==='admins'){echo '<section class="panel"><h2>Administradores</h2><p>Use o mesmo e-mail e senha da conta de usuário em admin.php. O administrador principal gerencia os acessos.</p>';foreach(sql("SELECT name,email FROM users WHERE role='ADMIN' ORDER BY id")->fetchAll() as $a)echo '<p><strong>'.e($a['name']).'</strong> · '.e($a['email']).'</p>';if((int)currentUser()['id']===(int)sql("SELECT MIN(id) FROM users WHERE role='ADMIN'")->fetchColumn()){beginForm('admin_access');field('admin_email','E-mail de uma conta cadastrada','','email',max:190);selectField('access','Acesso',['grant'=>'Conceder acesso administrativo','revoke'=>'Remover acesso administrativo']);submit('Salvar acesso');}echo '</section>';}
 elseif($tab==='audit'){echo '<div class="table-wrap"><table><thead><tr><th>Data (UTC)</th><th>Administrador</th><th>Ação</th><th>Alvo</th><th>Detalhes</th></tr></thead><tbody>';foreach(sql('SELECT a.*,u.name FROM audit a JOIN users u ON u.id=a.admin_id ORDER BY a.id DESC LIMIT 100')->fetchAll() as $a)echo '<tr><td>'.e($a['created_at']).'</td><td>'.e($a['name']).'</td><td>'.e($a['action']).'</td><td>'.(int)$a['target_id'].'</td><td>'.e($a['details']).'</td></tr>';echo '</tbody></table></div>';}
 else{
  $c=cfg();echo '<section class="form-panel wide"><h2>IA, e-mail e conteúdo</h2><p>Chaves e senhas ficam no servidor e não são exibidas. Os campos vazios mantêm os segredos já gravados.</p>';beginForm('settings');echo '<h3>Inteligência artificial</h3><label class="check-label"><input type="checkbox" name="ai_enabled" '.($c['ai']['enabled']?'checked':'').'>Ativar a integração de IA</label>';field('ai_key','Chave OpenAI (deixe vazio para manter)','',type:'password',required:false,max:500);field('ai_model','Modelo para análise de anúncios',$c['ai']['model'],max:80);echo '<label class="check-label"><input type="checkbox" name="clear_ai_key">Remover a chave e desativar a IA</label><label class="check-label"><input type="checkbox" name="auto_publish" '.($c['ai']['auto_publish']?'checked':'').'>Publicar automaticamente anúncios aprovados pela IA e sem alerta local</label><p class="help">Por padrão a equipe decide. A API pode ter custos para o operador; a plataforma continua gratuita para os usuários. Casos sinalizados ou falhas sempre aguardam revisão.</p><h3>E-mail</h3>';selectField('mail_transport','Envio',['mail'=>'PHP mail da hospedagem','smtp'=>'SMTP autenticado','disabled'=>'Desativado'],$c['mail']['transport']);field('mail_from','Remetente',$c['mail']['from'],type:'email',max:190);field('smtp_host','Servidor SMTP',$c['mail']['smtp_host'],required:false,max:190);selectField('smtp_port','Porta e segurança',['587'=>'587 — STARTTLS','465'=>'465 — SSL'],(string)$c['mail']['smtp_port']);field('smtp_user','Usuário SMTP',$c['mail']['smtp_user'],required:false,max:190);field('smtp_password','Senha SMTP (vazio mantém)','',type:'password',required:false,max:300);echo '<h3>Container Solidário</h3>';area('donation_text','Texto da página',$c['donation']['text']);field('donation_contact','Link oficial de contato HTTPS',$c['donation']['contact'],type:'url',required:false,max:500);echo '<h3>Responsável pela plataforma</h3>';field('operator_name','Nome / razão social',$c['operator']['name'],max:150);field('operator_contact','E-mail de suporte',$c['operator']['contact'],type:'email',max:190);field('general_contact','Contato geral, patrocínio e publicidade',publicContacts()['general'],type:'email',max:190);field('security_contact','Denúncias e segurança',publicContacts()['security'],type:'email',max:190);field('privacy_contact','E-mail para solicitações sobre dados',$c['operator']['privacy_contact'],type:'email',max:190);echo '<h3>Patrocínio e publicidade — página inicial</h3><p class="help">O botão abre um e-mail para o contato geral. Os valores e condições são combinados com sua equipe.</p>';$s=sponsorContent();field('sponsor_title','Título da chamada',$s['title'],max:160);area('sponsor_text','Texto da chamada',$s['text'],1200);field('sponsor_button','Texto do botão',$s['button'],max:80);submit('Salvar configurações');echo '<p class="help">Salve as configurações antes de testar. O teste será enviado ao e-mail da sua conta de administrador.</p>';beginForm('test_email');submit('Enviar e-mail de teste');echo '</section>';
 }
}
function renderPolicy(string $r):void{
 echo '<section class="reading-panel">';
 if($r==='how'){echo '<p class="eyebrow">TROKAR.IA</p><h1>Você tem. Alguém procura.</h1><ol><li>Crie sua conta e confirme o e-mail.</li><li>Mostre seu item, conte seu estado e indique seus interesses em troca.</li><li>Veja sugestões de interesses recíprocos ou explore os anúncios.</li><li>Faça propostas e converse. Você não precisa publicar anúncio para iniciar uma negociação.</li><li>Confira o produto, combine o encontro e confirme a troca depois de receber o seu item.</li></ol><p>A IA ajuda a interpretar interesses quando configurada. As sugestões não obrigam ninguém a trocar. As condições são sempre combinadas entre as pessoas.</p>';}
 elseif($r==='donations'){echo '<p class="eyebrow">CONTAINER SOLIDÁRIO</p><h1>Não quer trocar? Que tal doar?</h1><p class="preserve-text">'.e(cfg()['donation']['text']).'</p>';if(cfg()['donation']['contact']!=='')echo '<a class="button primary" href="'.e(cfg()['donation']['contact']).'" target="_blank" rel="noopener noreferrer">Contato oficial</a>';else echo '<p>Os pontos de coleta e o contato oficial serão divulgados pela equipe nesta página.</p>';}
 elseif($r==='rules'){echo '<h1>Boas trocas começam com respeito.</h1><ul><li>Somente objetos que você possui e pode oferecer, de origem lícita.</li><li>Animais vivos não podem ser anunciados para troca. Acessórios e itens para pets são permitidos.</li><li>Não são permitidos drogas ilícitas, armas, munições, documentos falsos, bens roubados ou conteúdo sexual explícito.</li><li>Descreva defeitos, acessórios e condições com honestidade; use fotos do seu próprio item.</li><li>Não são aceitos ameaças, assédio, discriminação, golpes ou divulgação de dados pessoais de terceiros.</li><li>Não envie dinheiro para garantir uma troca. Confira o item pessoalmente e escolha locais públicos.</li><li>Use o botão de denúncia quando identificar um problema. Você pode contestar uma recusa em Meus anúncios.</li></ul><h2>Moderação com contexto</h2><p>Textos e imagens podem ser analisados por inteligência artificial e pela equipe. Casos duvidosos aguardam revisão humana. Palavras são avaliadas no contexto, e uma sugestão automática pode ser revisada.</p><p>O Trokar.ia não recebe pagamentos nem organiza entregas. As pessoas decidem se querem negociar e combinam a troca diretamente.</p>';}
 else{$c=cfg()['operator'];echo '<h1>Privacidade no Trokar.ia.</h1><p>Responsável pela plataforma: '.e($c['name']).'.</p><h2>Dados usados</h2><p>Guardamos nome, e-mail, senha protegida por hash, cidade e estado, anúncios, fotos, favoritos, propostas, mensagens, denúncias e registros administrativos. Um cookie de sessão mantém o acesso à sua conta; não incluímos ferramentas de publicidade ou análise de visitas.</p><h2>O que é público</h2><p>Anúncios aprovados mostram o nome do anunciante e a cidade/estado do item. E-mail, senha e conversas não ficam públicos. As fotos são reprocessadas para remover metadados; evite imagens que exibam documentos, endereços ou pessoas sem autorização.</p><h2>IA e revisão humana</h2><p>Quando a integração de IA está ativada, o texto e as fotos dos anúncios, e o texto das mensagens para moderação, podem ser enviados à OpenAI para análise. Não enviamos sua senha nem seu e-mail nessa análise. A equipe pode revisar anúncios, mensagens sinalizadas, denúncias e contestações.</p><h2>Seus controles</h2><p>Você pode editar ou excluir anúncios, baixar seus dados em Minha conta e encerrar sua conta. Ao encerrar, seu perfil é anonimizado e seus anúncios deixam de ser públicos. Mensagens e registros das negociações permanecem vinculados a um perfil anonimizado para preservar o contexto e permitir análise de denúncias. Fotos removidas e registros técnicos devem ser tratados pela equipe conforme a política de retenção operacional.</p>';if($c['privacy_contact']!=='')echo '<p>Solicitações sobre seus dados: <a href="mailto:'.e($c['privacy_contact']).'">'.e($c['privacy_contact']).'</a>.</p>';else echo '<p>O contato responsável por dados será informado pela equipe nesta página.</p>';}
 if(cfg()['operator']['contact']!=='')echo '<p>Suporte: <a href="mailto:'.e(cfg()['operator']['contact']).'">'.e(cfg()['operator']['contact']).'</a>.</p>';echo '</section>';
}
function renderReport(bool $appeal=false):void{$u=requireUser();$lid=(int)($_GET[$appeal?'id':'listing_id']??0);$pid=(int)($_GET['proposal_id']??0);$mid=(int)($_GET['message_id']??0);if($appeal)$l=ownListing($lid);elseif($lid)$l=listing($lid);elseif($pid)thread($pid);else throw new RuntimeException('Conteúdo inválido.');echo '<section class="form-panel"><h1>'.($appeal?'Contestar decisão.':'Denunciar conteúdo.').'</h1><p>A equipe fará a revisão. Descreva o problema com clareza.</p>';beginForm($appeal?'appeal':'report');hidden('listing_id',$lid);hidden('proposal_id',$pid);hidden('message_id',$mid);area('reason',$appeal?'Por que a decisão deve ser revista?':'O que precisa ser analisado?','',1500);submit($appeal?'Enviar contestação':'Enviar denúncia');echo '</section>';}
function renderCloseAccount():void{requireUser();echo '<section class="form-panel"><h1>Encerrar minha conta.</h1><p>Seu perfil será anonimizado, seus anúncios sairão do ar e suas sessões serão encerradas. Registros de conversas e denúncias permanecerão associados ao perfil anonimizado. Esta ação não pode ser desfeita.</p>';beginForm('close_account');field('password','Confirme sua senha','',type:'password',max:72);echo '<label class="check-label"><input type="checkbox" name="confirm" required>Quero encerrar minha conta e retirar meus anúncios.</label>';submit('Encerrar conta');echo '</section>';}
